SELECT
  (SELECT CASE WHEN 'Bruce Guthro' IN (
      SELECT member_name FROM band_members WHERE band_name = 'Radiohead'
    ) THEN 'Yes' ELSE 'No' END) AS is_bruce_guthro_in_radiohead,
  (SELECT member_name FROM band_members WHERE band_name = 'Radiohead' AND song_performers LIKE '%All I Need%') AS performer_on_all_i_need
FROM dual;

