            rdfs:label "The Deal"@en ;
            dbo:starring ?actorDeal ;
            dbo:director ?dealDirector .

  ?actorDeal rdfs:label ?actorOfficeName .

  ?dealDirector rdfs:label ?dealDirectorName .
  FILTER (lang(?actorOfficeName) = "en")
  FILTER (lang(?dealDirectorName) = "en")
