SELECT ?position ?team ?year WHERE {
  ?person wdt:P31 wd:Q5;
          rdfs:label "Kevin Wilson"@en;
          p:P106 ?statement.
  ?statement ps:P106 ?occupation;
             pq:P580 ?startDate;
             pq:P582 ?endDate.
  ?occupation rdfs:label ?position.
  FILTER(CONTAINS(LCASE(?position), "offensive coordinator") || CONTAINS(LCASE(?position), "head coach"))
  BIND(YEAR(?startDate) AS ?startYear)
  BIND(YEAR(?endDate) AS ?endYear)
  FILTER(?startYear <= 2013 && ?endYear >= 2013)
  ?person wdt:P54 ?teamEntity.
  ?teamEntity rdfs:label ?team.
  FILTER(CONTAINS(?team, "Ohio State") || CONTAINS(?team, "Big Ten"))
  BIND(?startYear AS ?year)
}
ORDER BY ?year

