SELECT ?kerberOrigin ?kerberSport ?defChamp ?defChampSport WHERE {
  ?kerber wdt:P31 wd:Q5;           # instance of human
         rdfs:label "Angelique Kerber"@en;
         wdt:P27 ?kerberOrigin;    # country of citizenship
         wdt:P106 ?kerberSport.   # occupation

  ?event wdt:P31 wd:Q173445;       # tennis tournament
         rdfs:label "2005 China Open – Men's Doubles"@en;
         wdt:P1346 ?defChamp.      # winner (defending champion)

  ?defChamp wdt:P106 ?defChampSport.

  FILTER(CONTAINS(LCASE(STR(?kerberOrigin)), "texas") || CONTAINS(LCASE(STR(?kerberOrigin)), "united states"))
  FILTER(CONTAINS(LCASE(STR(?kerberSport)), "tennis player"))
  FILTER(CONTAINS(LCASE(STR(?defChampSport)), "tennis player"))
} LIMIT 10
